(()=>{'use strict';const $=id=>document.getElementById(id);let profiles=[],scene,camera,renderer,world,stars,last=performance.now(),frames=0;let active='aurora-native';const palette={Aurora:0x67dfff,Linux:0x8d7cff,Windows:0x55b8ff,Retro:0xffb86b};function esc(v){return String(v).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]))}function init(){if(!window.THREE){$('renderer').textContent='WebGL unavailable';return}const c=$('desktopGL');try{renderer=new THREE.WebGLRenderer({canvas:c,antialias:true,alpha:true,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio||1,2));renderer.setSize(innerWidth,innerHeight);scene=new THREE.Scene();scene.fog=new THREE.FogExp2(0x061021,.02);camera=new THREE.PerspectiveCamera(55,innerWidth/innerHeight,.1,300);camera.position.set(0,4,20);world=new THREE.Group();scene.add(world);world.add(new THREE.HemisphereLight(0xc9e7ff,0x050b15,2));const light=new THREE.PointLight(palette.Aurora,180,80);light.position.set(0,8,8);world.add(light);const floor=new THREE.Mesh(new THREE.PlaneGeometry(180,90),new THREE.MeshStandardMaterial({color:0x0a2138,metalness:.25,roughness:.22}));floor.rotation.x=-Math.PI/2;floor.position.y=-3;world.add(floor);const geo=new THREE.BufferGeometry(),pos=[];for(let i=0;i<1800;i++)pos.push((Math.random()-.5)*180,Math.random()*65-6,-Math.random()*120);geo.setAttribute('position',new THREE.Float32BufferAttribute(pos,3));stars=new THREE.Points(geo,new THREE.PointsMaterial({color:0xdaf3ff,size:.07,transparent:true,opacity:.75}));world.add(stars);window.addEventListener('resize',resize);renderer.setAnimationLoop(t=>{world.rotation.y=Math.sin(t*.00008)*.03;stars.rotation.y=t*.000004;renderer.render(scene,camera);frames++;if(t-last>1000){$('fps').textContent=String(frames);frames=0;last=t}});$('renderer').textContent='WebGL 2 · live'}catch(e){$('renderer').textContent='WebGL error'}}function resize(){if(!renderer)return;camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)}function setProfile(p){active=p.id;const color=palette[p.family]||palette.Aurora;$('desktopTitle').textContent=p.title;$('desktopMeta').textContent=p.family+' · '+p.mode;$('heroTitle').textContent=p.family.toUpperCase();$('heroDesc').textContent=p.description+' WebGL surface is browser-native; real host sessions require an authorized backend.';if(world){world.traverse(o=>{if(o.isLight)o.color.setHex(color)});scene.fog.color.setHex((color^0x111111)&0xffffff)}$('profiles').classList.remove('open')}function renderProfiles(){const groups={};profiles.forEach(p=>(groups[p.family]??=[]).push(p));$('profiles').innerHTML=Object.entries(groups).map(([f,ps])=>'<div class="profile-family">'+esc(f)+'</div>'+ps.map(p=>'<button type="button" data-profile="'+esc(p.id)+'">'+esc(p.title)+'</button>').join('')).join('');$('profiles').querySelectorAll('[data-profile]').forEach(b=>b.onclick=()=>setProfile(profiles.find(p=>p.id===b.dataset.profile)||profiles[0]))}function runtime(){const d=$('runtimeDialog');$('runtimeContent').innerHTML=['Firmware','Koronos Kernel','Memory Manager','Scheduler','IPC / Capability Bus','Drivers','Kore Init','hardware.target','storage.target','network.target','security.target','graphics.target','desktop.target','live.target','multi-user.target','System Services','Aurora Userspace'].map((x,i)=>'<div class="runtime-row"><span>'+esc(x)+'</span><b class="ready">ready</b></div>').join('');d.showModal()}$('launcher').onclick=()=>$('profiles').classList.toggle('open');$('runtime').onclick=runtime;$('fullscreen').onclick=()=>document.documentElement.requestFullscreen?.();$('settings').onclick=()=>alert('WebGL renderer: adaptive pixel ratio, antialiasing, WebGL 2, live FPS telemetry.');$('home').onclick=()=>location.href='index.html';fetch('desktop_profiles.json',{cache:'no-store'}).then(r=>r.json()).then(x=>{profiles=x.profiles||[];renderProfiles();setProfile(profiles.find(p=>p.id===active)||profiles[0])}).catch(()=>{});init()})();